using Microsoft.EntityFrameworkCore;

class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
        => options.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
            databaseName: "AppDb");

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(b =>
        {
            b.ToContainer("Products");

            // EF Core 9 breaking change: the default discriminator property
            // changed from "Discriminator" to "$type". Existing documents
            // already store "Discriminator", so explicitly preserve the old name
            // to avoid data mismatches.
            b.HasDiscriminator<string>("Discriminator");
        });
    }
}

class Product
{
    public string Id { get; set; } = null!;
    public string Name { get; set; } = null!;
}

class CosmosQueryService
{
    // EF Core 9 breaking change: synchronous Cosmos DB queries are no longer
    // supported and throw InvalidOperationException. All queries must be async.

    // BEFORE (broken in EF Core 9):
    // List<Product> GetAll(CosmosDbContext db) => db.Products.ToList();

    // AFTER:
    async Task<List<Product>> GetAllAsync(CosmosDbContext db)
        => await db.Products.ToListAsync();

    async Task<Product?> FindByNameAsync(CosmosDbContext db, string name)
        => await db.Products.FirstOrDefaultAsync(p => p.Name == name);
}

